import{_ as a,o as r,c as l,a2 as e}from"./chunks/framework.A5mep7Fe.js";const c=JSON.parse('{"title":"🔍 01 · AI 技术本质判断","description":"","frontmatter":{},"headers":[],"relativePath":"00-导论与学习哲学/01-AI技术本质判断.md","filePath":"00-导论与学习哲学/01-AI技术本质判断.md","lastUpdated":1786806808000}'),o={name:"00-导论与学习哲学/01-AI技术本质判断.md"};function d(i,t,n,s,h,g){return r(),l("div",null,[...t[0]||(t[0]=[e('<h1 id="🔍-01-·-ai-技术本质判断" tabindex="-1">🔍 01 · AI 技术本质判断 <a class="header-anchor" href="#🔍-01-·-ai-技术本质判断" aria-label="Permalink to &quot;🔍 01 · AI 技术本质判断&quot;">​</a></h1><blockquote><p>核心能力：面对一个全新的 AI 概念（比如今天的「世界模型」、明天的某个新架构），你能在 30 分钟内判断——<strong>它值得我投入多少？</strong></p></blockquote><hr><h2 id="一、本质判断的五问框架" tabindex="-1">一、本质判断的五问框架 <a class="header-anchor" href="#一、本质判断的五问框架" aria-label="Permalink to &quot;一、本质判断的五问框架&quot;">​</a></h2><p>拿到任何新技术，依次问自己这 5 个问题。能答清楚，就不容易被营销话术带跑。</p><h3 id="q1-它解决什么「真问题」-problem" tabindex="-1">Q1：它解决什么「真问题」？（Problem） <a class="header-anchor" href="#q1-它解决什么「真问题」-problem" aria-label="Permalink to &quot;Q1：它解决什么「真问题」？（Problem）&quot;">​</a></h3><ul><li>是解决了<strong>此前做不到的事</strong>（如 ChatGPT 的通用对话），还是<strong>把已有事做得更便宜/更快</strong>（如模型量化降本）？</li><li>前者往往开创赛道（高价值、高不确定），后者往往是工程优化（稳健、可累积）。</li></ul><h3 id="q2-它的「第一性原理」是什么-principle" tabindex="-1">Q2：它的「第一性原理」是什么？（Principle） <a class="header-anchor" href="#q2-它的「第一性原理」是什么-principle" aria-label="Permalink to &quot;Q2：它的「第一性原理」是什么？（Principle）&quot;">​</a></h3><ul><li>用一句话说清它依赖的核心思想。例： <ul><li>Transformer → 「用注意力机制并行建模任意两 token 的依赖，抛弃 RNN 的时序瓶颈」。</li><li>Diffusion → 「通过逐步去噪从随机噪声生成数据，把生成建模为可学习的逆扩散过程」。</li></ul></li></ul><h3 id="q3-它的核心代价-局限是什么-trade-off" tabindex="-1">Q3：它的核心代价/局限是什么？（Trade-off） <a class="header-anchor" href="#q3-它的核心代价-局限是什么-trade-off" aria-label="Permalink to &quot;Q3：它的核心代价/局限是什么？（Trade-off）&quot;">​</a></h3><ul><li>没有免费午餐。每个技术都有代价：算力、显存、推理延迟、数据需求、可解释性、稳定性。</li><li><strong>能清楚说出代价的技术，才是成熟技术；只说好处不说代价的是早期炒作。</strong></li></ul><h3 id="q4-它经过了几界的验证-validation" tabindex="-1">Q4：它经过了几界的验证？（Validation） <a class="header-anchor" href="#q4-它经过了几界的验证-validation" aria-label="Permalink to &quot;Q4：它经过了几界的验证？（Validation）&quot;">​</a></h3><ul><li><strong>工业界</strong>：有没有大公司在生产环境大规模用？（最硬核的证据）</li><li><strong>学术界</strong>：顶会是否持续产出、是否从「惊艳一篇」变成「每年几十篇」？</li><li><strong>竞赛界</strong>：Kaggle/各类基准上是否成为标配打法？</li><li><strong>投资界</strong>：资本是「all-in 讲故事」还是「冷静投基础设施」？</li><li><strong>应用界</strong>：有没有真实用户、真实付费场景？</li><li>五界中验证越多，跨周期价值越高 → 进入本项目核心；反之进「观察区」。</li></ul><h3 id="q5-它和我已有的能力是否可叠加-leverage" tabindex="-1">Q5：它和我已有的能力是否可叠加？（Leverage） <a class="header-anchor" href="#q5-它和我已有的能力是否可叠加-leverage" aria-label="Permalink to &quot;Q5：它和我已有的能力是否可叠加？（Leverage）&quot;">​</a></h3><ul><li>最好的学习是「复利型」：新学的技术能增强你已有的能力网。</li><li>例：你已懂 Transformer，学 MoE 只是「在 Transformer 上换路由」，成本极低、收益很高 → 立刻学。反之，一个和你主航道完全无关的方向，除非战略需要，否则标记为「待观察」。</li></ul><hr><h2 id="二、判断的「时间维度」-热点-vs-跨周期" tabindex="-1">二、判断的「时间维度」：热点 vs 跨周期 <a class="header-anchor" href="#二、判断的「时间维度」-热点-vs-跨周期" aria-label="Permalink to &quot;二、判断的「时间维度」：热点 vs 跨周期&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>热点型技术（观察区）</th><th>跨周期技术（核心区）</th></tr></thead><tbody><tr><td>来源</td><td>一篇论文/一个产品引爆</td><td>多界多年持续验证</td></tr><tr><td>半衰期</td><td>6-18 个月</td><td>5 年以上</td></tr><tr><td>学习建议</td><td>了解概念即可，不深投</td><td>必须吃透原理与推导</td></tr><tr><td>例子（历史）</td><td>早期 GAN 各种花式变体</td><td>反向传播、注意力机制、梯度优化</td></tr><tr><td>例子（当下）</td><td>某具体 Agent 框架（易过时）</td><td>Agent 的「规划-记忆-工具」范式本身</td></tr></tbody></table><blockquote><p>💡 <strong>框架会过时，范式永留存。</strong> 本书对框架（LangChain/LlamaIndex 等）只讲「思想与适用边界」，对范式（RAG/Agent/对齐）讲「原理与推导」。</p></blockquote><hr><h2 id="三、给「是否值得投入」的量化决策表" tabindex="-1">三、给「是否值得投入」的量化决策表 <a class="header-anchor" href="#三、给「是否值得投入」的量化决策表" aria-label="Permalink to &quot;三、给「是否值得投入」的量化决策表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>信号</th><th>权重</th><th>你的打分（0-3）</th></tr></thead><tbody><tr><td>解决真问题（非玩具）</td><td>高</td><td>?</td></tr><tr><td>第一性原理清晰</td><td>中</td><td>?</td></tr><tr><td>代价已知且可接受</td><td>中</td><td>?</td></tr><tr><td>工业界已落地</td><td>高</td><td>?</td></tr><tr><td>与你能力可叠加</td><td>中</td><td>?</td></tr><tr><td>5 年后仍重要的概率</td><td>高</td><td>?</td></tr></tbody></table><p><strong>决策阈值</strong>：</p><ul><li>总分 ≥ 13 / 18 → <strong>立刻投入，学透原理</strong>。</li><li>9-12 → <strong>学习概念与边界，等下一轮验证再加码</strong>。</li><li>&lt; 9 → <strong>列入观察区，不分配深度学习时间</strong>。</li></ul><hr><h2 id="四、面试中如何展现「本质判断」-高频加分项" tabindex="-1">四、面试中如何展现「本质判断」？（高频加分项） <a class="header-anchor" href="#四、面试中如何展现「本质判断」-高频加分项" aria-label="Permalink to &quot;四、面试中如何展现「本质判断」？（高频加分项）&quot;">​</a></h2><p>面试官最爱问的不是「你知道 X 吗」，而是「<strong>你怎么看 X 的未来 / X 的局限 / 为什么选 X 而不选 Y</strong>」。</p><ul><li>❌ 错误回答：「X 很火，效果很好。」</li><li>✅ 正确回答：「X 解决的是 Y 问题，它的核心思想是 Z，代价是 W；在我们这个场景（数据量小/延迟敏感），我倾向 A 而非 X，因为……」</li></ul><p>→ 这种回答<strong>会直接把你和普通背题者区分开</strong>，也是本书每个知识点都附「本质判断」与「高频追问」的原因。</p><hr><h2 id="五、本项目的「本质判断」标注约定" tabindex="-1">五、本项目的「本质判断」标注约定 <a class="header-anchor" href="#五、本项目的「本质判断」标注约定" aria-label="Permalink to &quot;五、本项目的「本质判断」标注约定&quot;">​</a></h2><p>全书知识点会带以下标签之一：</p><ul><li>🟢 <strong>跨周期核心</strong>：多界验证，建议学透。</li><li>🟡 <strong>稳健工程</strong>：落地价值高，重点学应用。</li><li>🔵 <strong>前沿观察</strong>：方向重要但未定论，了解范式、跟踪进展。</li><li>🔴 <strong>谨慎对待</strong>：炒作成分高或局限明显，了解即可。</li></ul><hr><p>➡️ 下一步：<a href="./02-跨周期价值技术地图">02-跨周期价值技术地图</a></p>',35)])])}const b=a(o,[["render",d]]);export{c as __pageData,b as default};
